import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { Users, Eye } from "lucide-react";

export default function LiveCounter() {
  const [visitors, setVisitors] = useState(247);
  const [activeNow, setActiveNow] = useState(18);

  // Simulate live visitor count changes
  useEffect(() => {
    const interval = setInterval(() => {
      // Randomly increment visitors occasionally
      setVisitors(v => {
        const change = Math.random() > 0.7 ? 1 : 0;
        return v + change;
      });

      // Randomly change active viewers
      setActiveNow(a => {
        const change = Math.random() > 0.5 ? 1 : -1;
        return Math.max(5, Math.min(30, a + change));
      });
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  return (
    <motion.div
      initial={{ opacity: 0, x: -100 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ delay: 3, duration: 0.5 }}
      className="fixed bottom-6 left-24 z-40"
    >
      <div
        className="px-4 py-3 rounded-2xl shadow-lg"
        style={{
          background: "linear-gradient(135deg, rgba(255,255,255,0.98), rgba(250,248,245,0.98)",
          border: "1px solid rgba(212,175,55,0.3)",
          boxShadow: "0 8px 32px rgba(212,175,55,0.15)"
        }}
      >
        {/* Live Indicator */}
        <div className="flex items-center gap-2 mb-2">
          <div className="relative">
            <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
          </div>
          <span className="text-xs font-semibold uppercase tracking-wider" style={{ color: "#d4af37" }}>
            Live
          </span>
        </div>

        {/* Visitor Count */}
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1">
            <Users size={16} color="#1a080a" />
            <span className="text-lg font-bold" style={{ color: "#1a080a" }}>
              {visitors.toLocaleString()}
            </span>
          </div>
          <div className="text-xs" style={{ color: "rgba(26,8,10,0.5)" }}>
            visitors
          </div>
        </div>

        {/* Active Now */}
        <div className="flex items-center gap-2 mt-1 text-xs" style={{ color: "rgba(26,8,10,0.5)" }}>
          <Eye size={12} />
          <span><strong style={{ color: "#d4af37" }}>{activeNow}</strong> viewing now</span>
        </div>

        {/* Activity Bar */}
        <div className="mt-2 h-1 rounded-full overflow-hidden" style={{ background: "rgba(212,175,55,0.2)" }}>
          <motion.div
            className="h-full rounded-full"
            style={{ background: "linear-gradient(90deg, #d4af37, #f4d77a)" }}
            animate={{ width: [`${Math.min(100, (activeNow / 30) * 100)}%`, `${Math.min(100, ((activeNow + 5) / 30) * 100)}%`] }}
            transition={{ duration: 2, repeat: Infinity, repeatType: "reverse" }}
          />
        </div>
      </div>
    </motion.div>
  );
}
